#include "ASCIIart.h"
#include <ncurses.h>
#include <cstring>

// General Print
//  -1 -1 in col e row -> la funzione centra l'Art
//altrimenti bisgona fornire il centro dell'immagine
void print(const char *art[], const int size, int row, int col, utl::colorPair color){
    int maxRow, maxCol;
    getmaxyx(stdscr, maxRow, maxCol);
    if (row == -1)
        row = maxRow/2;
    if (col == -1)
        col = maxCol/2;

    col -= ((int)strlen(art[0])/2);
    row -= (size/2);

    if(row < 0) row = 0;
    if(col < 0) col = 0;

    attron(COLOR_PAIR(color) | A_BOLD);

    for (int i = 0; i < size; i++)
        mvprintw(row + i, col, "%s", art[i]);
    attroff(COLOR_PAIR(color) | A_BOLD);
}

